  jsonb_build_object('bmPrints', $prints$[{"nome":"Campanhas · últimos 14 dias","reportKey":"2026-09-18-14d","img":"data:image/jpeg;base64,"},{"nome":"Campanhas · ontem","reportKey":"2026-09-18-1d","img":"data:image/jpeg;base64,"},{"nome":"Campanhas · últimos 7 dias","reportKey":"2026-09-18-7d","img":"data:image/jpeg;base64,"},{"nome":"Campanhas · últimos 30 dias","reportKey":"2026-09-18-30d","img":"data:image/jpeg;base64,"},{"nome":"Anúncios · visão de 7 dias","reportKey":"2026-09-18-7d","img":"data:image/jpeg;base64,"},{"nome":"Conjuntos de anúncios · 7 dias","reportKey":"2026-09-18-7d","img":"data:image/jpeg;base64,"},{"nome":"Configuração · público","reportKey":"2026-09-18-7d","img":"data:image/jpeg;base64,"},{"nome":"Configuração · conversão","reportKey":"2026-09-18-7d","img":"data:image/jpeg;base64,"},{"nome":"Histórico de orçamento","reportKey":"2026-09-18-30d","img":"data:image/jpeg;base64,"},{"nome":"Configuração · orçamento","reportKey":"2026-09-18-30d","img":"data:image/jpeg;base64,"},{"nome":"Configuração · período do anúncio","reportKey":"2026-09-18-30d","img":"data:image/jpeg;base64,"}]$prints$::jsonb)
